const SLAVE_ID = 1;
const START_ADDR = 0;
const NUM_REGS = 14;

function crc16(buf) {
    let crc = 0xFFFF;
    for (let i = 0; i < buf.length; i++) {
        crc ^= buf[i];
        for (let j = 0; j < 8; j++) {
            if (crc & 0x0001) crc = (crc >> 1) ^ 0xA001;
            else crc >>= 1;
        }
    }
    return crc;
}

let buf = Buffer.alloc(6);
buf.writeUInt8(SLAVE_ID, 0);
buf.writeUInt8(0x03, 1);
buf.writeUInt16BE(START_ADDR, 2);
buf.writeUInt16BE(NUM_REGS, 4);
let crc = crc16(buf);
let request = Buffer.concat([buf, Buffer.from([crc & 0xFF, (crc >> 8) & 0xFF])]);

msg.payload = request;
return msg;

// ===== FETCH DATA =====
let data = msg.payload;

// ===== BASIC LENGTH CHECK =====
// Expected: 1 (ID) + 1 (Func) + 1 (Byte Count) + 28 (Data) + 2 (CRC) = 33 bytes
if (!data || data.length !== 33) {
    node.error("Invalid message length: " + (data ? data.length : "null"));
    return null;
}

// ===== HEADER CHECK =====
const EXPECT_ID = 0x01;
const EXPECT_FUNC = 0x03;
const EXPECT_BYTES = 0x1C; // 28 bytes

if (data[0] !== EXPECT_ID || data[1] !== EXPECT_FUNC || data[2] !== EXPECT_BYTES) {
    node.error("Invalid header: " + data.slice(0, 3).toString("hex"));
    return null;
}

// ===== CRC CHECK =====
function calcCRC(buffer) {
    let crc = 0xFFFF;

    for (let i = 0; i < buffer.length - 2; i++) {
        crc ^= buffer[i];

        for (let j = 0; j < 8; j++) {
            if (crc & 0x0001) {
                crc >>= 1;
                crc ^= 0xA001;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

// Calculate CRC
let crcCalculated = calcCRC(data);

// Extract received CRC (LOW byte first, HIGH byte second)
let crcReceived = data[data.length - 2] | (data[data.length - 1] << 8);

// Compare
if (crcCalculated !== crcReceived) {
    node.error("CRC mismatch: calc=" + crcCalculated + " recv=" + crcReceived);
    return null;
}

// ===== PASS RESULT =====
msg.valid = true;

// Optional: extract clean data (remove header + CRC)
msg.data = data.slice(3, data.length - 2);

return msg;

