const INDEX = 1;
const flow_rate = "Flow Rate";

// ===== FETCH DATA =====
let data = msg.payload;

// ambil data lenght sahaja 14bytes hexa
let d = data.slice(3, data.length - 2);

// ===== MSB SWAP 1234 to 3412 =====
function toFloat(b0, b1, b2, b3) {
    let buf = Buffer.from([b2, b3, b0, b1]); // MSB word swap
    return buf.readFloatBE(0);
}

// ===== CALCULATE OFFSET UNTUK SETIAP 4BYTES DATA =====
let i = INDEX * 4;

// ===== OUTPUT =====
msg.payload = {};
msg.payload[flow_rate] = toFloat(
    d[i],
    d[i+1],
    d[i+2],
    d[i+3]
);

return msg;

